{"implementation":"def solve(case):
    payload = case.get("payload", case)
    threshold = payload["threshold"]
    selected_call_ids = []

    for call in payload.get("calls", []):
        if not call.get("parseable", False):
            continue

        prediction_tokens = call.get("prediction_tokens", 0)
        if prediction_tokens <= 0:
            continue

        effect_per_token = (
            call["loss_without_call"] - call["loss_with_call"]
        ) / prediction_tokens
        if effect_per_token >= threshold:
            selected_call_ids.append(call["call_id"])

    return {"selected_call_ids": selected_call_ids}
"}
